mapper.select:
SELECT 
FROM words w
LEFT JOIN user_word_progress p
    ON p.word_id = w.id AND p.user_id = #{userId}
WHERE w.book_id = #{bookId}

    AND (
        LOWER(w.word) LIKE CONCAT('%', LOWER(#{keyword}), '%')
        OR w.chinese_meaning LIKE CONCAT('%', #{keyword}, '%')
        OR w.korean_meaning LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY w.priority_rank, w.id
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM words w
LEFT JOIN user_word_progress p
    ON p.word_id = w.id AND p.user_id = #{userId}
WHERE w.id = #{wordId}

SELECT 
FROM words w
JOIN user_word_progress p
    ON p.word_id = w.id AND p.user_id = #{userId}
WHERE w.book_id = #{bookId}
  AND p.next_review_at <= #{now}
ORDER BY p.next_review_at, w.priority_rank, w.id
LIMIT #{limit}

SELECT 
FROM words w
LEFT JOIN user_word_progress p
    ON p.word_id = w.id AND p.user_id = #{userId}
WHERE w.book_id = #{bookId}
  AND p.id IS NULL
ORDER BY w.priority_rank, w.id
LIMIT #{limit}
